        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0L
        while (c > 32 && c != -1) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) value else -value
    }
}

