import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val SIZE = 6

private fun normalize(value: Long, mod: Long): Long {
    val result = value % mod
    return if (result < 0) result + mod else result
}

private fun multiply(a: Array<LongArray>, b: Array<LongArray>, mod: Long): Array<LongArray> {
    val result = Array(SIZE) { LongArray(SIZE) }

    for (i in 0 until SIZE) {
        for (k in 0 until SIZE) {
            if (a[i][k] == 0L) continue
            for (j in 0 until SIZE) {
                if (b[k][j] == 0L) continue
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
            }
        }
    }

    return result
}

private fun power(matrix: Array<LongArray>, exponent: Long, mod: Long): Array<LongArray> {
    var base = matrix
    var exp = exponent
    var result = Array(SIZE) { i ->
        LongArray(SIZE) { j -> if (i == j) 1L % mod else 0L }
    }

    while (exp > 0) {
        if ((exp and 1L) != 0L) {
            result = multiply(result, base, mod)
        }
        base = multiply(base, base, mod)
        exp = exp shr 1
    }

    return result
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())

    val n = st.nextToken().toLong()
    val sx = st.nextToken().toLong()
    val sy = st.nextToken().toLong()
    val dx = st.nextToken().toLong()
    val dy = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    if (n == 1L) {
        print("1 1")
        return
    }

    val transition = arrayOf(
        longArrayOf(2, 1, 1, 0, 1, 0),
        longArrayOf(1, 2, 0, 1, 1, 0),
        longArrayOf(1, 1, 1, 0, 1, 0),
        longArrayOf(1, 1, 0, 1, 1, 0),
        longArrayOf(0, 0, 0, 0, 1, 1),
        longArrayOf(0, 0, 0, 0, 0, 1)
    )

    val powered = power(transition, t, n)
    val state = longArrayOf(
        sx % n,
        sy % n,
        normalize(dx, n),
        normalize(dy, n),
        0L,
        1L
    )

    val result = LongArray(SIZE)
    for (i in 0 until SIZE) {
        for (j in 0 until SIZE) {
            result[i] = (result[i] + powered[i][j] * state[j]) % n
        }
    }

    val finalX = if (result[0] == 0L) n else result[0]
    val finalY = if (result[1] == 0L) n else result[1]

    print("$finalX $finalY")
}
